// The icon as an SVG document in `color`, at `size` px, for an Image. A
// translucent QML color comes as #AARRGGBB, which SVG would read as
// #RRGGBBAA: the alpha goes to the group's opacity instead.
function svg(name, color) {
  var ic = set[name]
  if (!ic) return ""
  var c = String(color), a = 1
  if (/^#[0-9a-fA-F]{8}$/.test(c)) { a = parseInt(c.substr(1, 2), 16) / 255; c = "#" + c.substr(3) }
  var body = ic[1].replace(/currentColor/g, c)
  if (a < 1) body = "<g opacity='" + a.toFixed(3) + "'>" + body + "</g>"
  return "<svg xmlns='http://www.w3.org/2000/svg' viewBox='" + ic[0] + "'>" + body + "</svg>"
}

function url(name, color) {
  var s = svg(name, color)
  return s ? "data:image/svg+xml;utf8," + encodeURIComponent(s) : ""
}
